class WebhooksApi:
    """Webhooks in the Public API."""

    def __init__(self, transport: Transport) -> None:
        self._t = transport

    def list(self) -> WebhookList:
        """Lists the organisation's webhooks. Scope webhooks:manage. Newest first, each with its last delivery; never with its secret."""
        return self._t.request("GET", "/api/v1/webhooks")  # type: ignore[no-any-return]

    def create(self, body: "WebhookRequest") -> CreatedWebhook:
        """Creates a webhook. Scope webhooks:manage. The secret is in this answer only; keep it to check Askwerk-Signature. At most 20 webhooks per organisation."""
        return self._t.request("POST", "/api/v1/webhooks", body=body)  # type: ignore[no-any-return]

    def update(self, id: str, body: "WebhookChange") -> WebhookView:
        """Changes a webhook's URL, events or state. Scope webhooks:manage. active false stops it; active true starts it again, also after it was paused for failing."""
        return self._t.request("PATCH", f"/api/v1/webhooks/{id}", body=body)  # type: ignore[no-any-return]

    def delete(self, id: str) -> None:
        """Deletes a webhook and its deliveries log. Scope webhooks:manage."""
        return self._t.request("DELETE", f"/api/v1/webhooks/{id}")  # type: ignore[no-any-return]

    def deliveries(self, id: str, *, cursor: str | None = None, limit: int | None = None) -> DeliveryPage:
        """Lists a webhook's deliveries, newest first. Scope webhooks:manage. Cursor-based: pass nextCursor as cursor for the next page."""
        return self._t.request("GET", f"/api/v1/webhooks/{id}/deliveries", query={"cursor": cursor, "limit": limit})  # type: ignore[no-any-return]

    def deliveries_all(self, id: str, *, limit: int | None = None) -> Iterator[DeliveryView]:
        """Every item of deliveries, page after page."""
        return self._t.by_cursor(lambda cursor: self.deliveries(id, cursor=cursor, limit=limit))  # type: ignore[no-any-return]

    def replay(self, id: str, delivery_id: str) -> None:
        """Sends a delivery's event again. Scope webhooks:manage. A new delivery with the same event id, so receivers that saw it already can skip it."""
        return self._t.request("POST", f"/api/v1/webhooks/{id}/deliveries/{delivery_id}/replay")  # type: ignore[no-any-return]


class UsersApi:
    """Users in the Public API."""

    def __init__(self, transport: Transport) -> None:
        self._t = transport

    def list(self, *, cursor: str | None = None, limit: int | None = None) -> PublicUserPage:
        """Lists the provisioned users, oldest first. Scope users:manage. Pages on a cursor: pass nextCursor as cursor until it is null. Deactivated users are listed with active false."""
        return self._t.request("GET", "/api/v1/users", query={"cursor": cursor, "limit": limit})  # type: ignore[no-any-return]

    def list_all(self, *, limit: int | None = None) -> Iterator[PublicUser]:
        """Every item of list, page after page."""
        return self._t.by_cursor(lambda cursor: self.list(cursor=cursor, limit=limit))  # type: ignore[no-any-return]

    def put(self, external_id: str, body: "PublicUserRequest") -> PublicUser:
        """Creates or changes a user by the host's id. Scope users:manage. Creates the user (without an Askwerk password) when the id is new, matching an existing account by email once; otherwise updates email, name and role. active false deactivates, true activates again. Owners are never provisioned; an owner's role is never changed."""
        return self._t.request("PUT", f"/api/v1/users/{external_id}", body=body)  # type: ignore[no-any-return]

    def deactivate(self, external_id: str) -> None:
        """Deactivates a user: out of the organisation, sessions ended; never deleted, their responses stay. Scope users:manage. PUT with active true lets them in again."""
        return self._t.request("DELETE", f"/api/v1/users/{external_id}")  # type: ignore[no-any-return]
